import {agreementBlob} from './agreement.js';
import{example,stages,clientProject,encode,decode,validate,deliverableItems}from './model.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='roll-projects-v1';let projects=[],p,preview=false,readonly=location.hash.startsWith('#project='),storageOK=true;const dialog=$('#dialog');
try{projects=JSON.parse(localStorage.getItem(key)||'[]').filter(validate)}catch{storageOK=false}if(readonly){try{p=decode(location.hash.slice(9))}catch{$('#app').innerHTML='<div class="error"><h1>This link is incomplete.</h1><p>Ask Roll for a fresh project link.</p></div>';throw Error('Invalid shared project')}}else{if(!projects.length)projects=[example()];p=projects[0]}
function money(n){return new Intl.NumberFormat('en-NZ',{style:'currency',currency:p.currency,maximumFractionDigits:0}).format(n)}function date(s){return new Date(s+'T12:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',timeZone:'UTC'})}function save(){if(readonly)return;try{localStorage.setItem(key,JSON.stringify(projects));storageOK=true}catch{storageOK=false;toast('Storage is full or unavailable. Export a backup to keep this project.')}render()}function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function render(){const client=readonly||preview,s=stages(p),end=s.at(-1).end;document.title=`${p.title} — Seabird`;$('#actions').innerHTML=readonly?'':preview?'<button data-action="preview">← Back to editing</button><button class="primary" data-action="share">Share project ↗</button>':'<button data-action="projects">Projects</button><button data-action="preview">Client view</button><button class="primary" data-action="share">Share project ↗</button>';
$('#actions').insertAdjacentHTML('afterbegin','<button data-action="agreement">Agreement</button>');
$('#app').innerHTML=`${preview?'<div class="preview-banner">Client preview · your internal pricing is hidden</div>':''}<div class="meta"><span>Roll &nbsp; / &nbsp; For ${esc(p.client)}</span><span class="status"><i class="dot"></i>${readonly?'Project proposal':'Draft proposal'}</span></div><div class="intro"><div><h1>${esc(p.title)}</h1><p>${esc(p.description)}</p></div>${!client?'<button data-action="project">Edit project ↗</button>':''}</div><section class="timeline-card" aria-label="Project timeline"><div class="timeline-heading"><span class="section-label">The plan, in one line</span><span>${date(p.start)} — ${date(end)} · working days</span></div><div class="timeline-scroll"><div class="timeline">${s.map((v,i)=>`<button class="stage" data-stage="${i}" style="--stage:${v.color};flex:${Math.max(1,Math.min(3,(new Date(v.end)-new Date(v.start))/86400000/3))}" aria-label="${esc(v.name)}, ${date(v.start)} to ${date(v.end)}. View details"><span class="date">${date(v.start)}</span><span class="bar"></span><strong>${esc(v.name)}</strong><small>${esc(v.owner)}</small></button>`).join('')}</div></div><div class="timeline-note"><span class="legend"><i></i>Making</span><span class="legend"><i></i>Reviewing</span><span style="margin-left:auto">Click a moment for the details ↗</span></div></section><section class="overview"><div class="scope"><span class="section-label">What we're making</span><h2>A beginning worth watching.</h2><p>${esc(deliverableItems(p)[0]?.name||'Deliverables to be agreed')}</p><div class="tags"><span class="tag">${p.reviews} review rounds</span><span class="tag">${p.reviewDays} working days per review</span><span class="tag">${date(end)} delivery</span></div></div><div class="price"><span class="section-label">Project fee</span><div class="amount">${money(p.fee)}<small>${p.currency}</small></div><p>${esc(p.tax)} · ${p.deposit}% to get started</p>${!client?'<button class="text-button" data-action="pricing">Work out the price ↗</button>':'<span class="hint">Payment details below ↓</span>'}</div></section><section class="rows">
${row('01','The deliverables','What’s included',deliverableItems(p).map(v=>`<div class="deliverable"><b>${esc(v.name)}</b><p>${esc(v.specs||'Technical specifications to be agreed.')}</p></div>`).join(''),client?'':'scope')}
${row('02','Reviews & timing',`${p.reviews} rounds · ${p.reviewDays} days each`,`<b>${p.reviews} review rounds, with ${p.reviewDays} working days for each.</b>\nOne consolidated set of feedback per round. Dates run Monday–Friday; public holidays are not excluded.\n\n${s.map(v=>`${esc(v.name)}: ${date(v.start)}${v.end!==v.start?' – '+date(v.end):''} · ${esc(v.owner)}`).join('\n')}`,client?'':'schedule')}
${row('03','What we need from you',`By ${date(p.start)}`,`<b>${esc(p.client)} to supply by kick-off:</b>\n${esc(p.inputs)}`,client?'':'inputs')}
${row('04','Payments',`${p.deposit}% now · ${100-p.deposit}% at delivery`,`<div class="payment"><span><b>01 &nbsp; To book the project</b><br>${date(p.start)} · ${p.deposit}%</span><b>${money(Math.round(p.fee*p.deposit/100))}</b></div><div class="payment"><span><b>02 &nbsp; Before final masters</b><br>${date(end)} · ${100-p.deposit}%</span><b>${money(p.fee-Math.round(p.fee*p.deposit/100))}</b></div><p>${esc(p.paymentNote)}</p>`,client?'':'payments')}
${row('05','The working agreement','The small, important things',`${esc(p.terms)}\n\n<b>Usage & handover</b>\n${esc(p.rights)}`,client?'':'terms')}</section><div class="bottom-note"><span class="asterisk">✳</span><span>${readonly?'This is a proposal snapshot. Please confirm the scope, dates and terms with Roll before work begins.':'Everything in one place. Open a card to fine-tune the details, then preview what your client sees.'}</span></div>`;
$('#save-state').textContent=readonly?'Project snapshot · shared by Roll':storageOK?'Roll workspace · saved on this device':'Storage unavailable · export a backup';}
function row(n,title,summary,body,edit){
const descriptions={'01':'The items we will deliver, and their technical specifications.','02':'When we make, when you review, and when it is ready.','03':'The files and information we need to get started.','04':'How much is due, and when to pay it.','05':'Scope, changes, usage and the terms we agree to.'};
const icons={'01':'▤','02':'◷','03':'↓','04':'$','05':'≡'};
return `<details class="project-card" name="project-sections"><summary><span class="card-top"><span class="card-icon" aria-hidden="true">${icons[n]}</span><span class="num">${n}</span></span><span class="row-title">${title}</span><span class="card-description">${descriptions[n]}</span><span class="card-bottom"><span class="row-summary">${summary}</span><span class="plus">+</span></span></summary><div class="detail">${body}${edit?`<br><button data-action="${edit}">Edit details ↗</button>`:''}</div></details>`}
const field=(name,label,type='text',value=p[name],attrs='')=>`<label for="${name}">${label}</label>${type==='textarea'?`<textarea id="${name}" name="${name}" maxlength="10000">${esc(value)}</textarea>`:`<input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${attrs} required>`}`;
const num=(name,label,min=0,max=1000000)=>field(name,label,'number',p[name],`min="${min}" max="${max}" step="${['reviews','conceptDays','animationDays','reviewDays','finishDays'].includes(name)?1:0.01}"`);
function open(title,html,onSubmit,button='Save changes ↗'){ $('#dialog-title').textContent=title;$('#fields').innerHTML=html;$('#submit').textContent=button;$('#submit').hidden=!onSubmit;$('#form').onsubmit=e=>{e.preventDefault();if(onSubmit)onSubmit(new FormData(e.target))};dialog.showModal()}
function edit(kind){if(kind==='scope'){editDeliverables();return}let html='',title='';switch(kind){case'project':title='The project';html=field('title','Project name','text',p.title,'maxlength="200"')+field('client','Client','text',p.client,'maxlength="200"')+field('description','One-line description');break;case'scope':title='What’s included';html=field('deliverables','Deliverables · one per line','textarea');break;case'inputs':title='What the client supplies';html=field('inputs','Materials due at kick-off · one per line','textarea');break;case'terms':title='The working agreement';html=field('terms','Commercial terms','textarea')+field('rights','Usage, licences & source files','textarea');break;case'payments':title='When you get paid';html=num('deposit','Deposit (%)',0,100)+field('paymentNote','Payment terms','textarea')+field('tax','Tax wording');break;case'schedule':title='Make room for good work';html=field('start','Kick-off date','date')+'<div class="pair"><div>'+num('conceptDays','Direction (working days)',1,90)+'</div><div>'+num('animationDays','Animation (working days)',1,90)+'</div></div><div class="pair"><div>'+num('reviews','Review rounds',1,6)+'</div><div>'+num('reviewDays','Days for each review',1,90)+'</div></div>'+num('finishDays','Refinement / delivery days',1,90)+'<p class="hint">Changing a duration moves later stages automatically. Weekends are skipped; public holidays are not. Review 1 follows direction; later reviews follow animation.</p>';break;case'pricing':title='A price that adds up';html='<p class="hint">Only you see the working numbers. Your client sees the agreed project fee.</p><div class="pair"><div>'+num('rate','Day rate')+'</div><div>'+num('days','Estimated days',0.5,1000)+'</div></div>'+num('costs','Other costs')+'<div class="calc"><span>Working estimate</span><b id="estimate"></b></div>'+num('fee','Agreed project fee')+'<label for="currency">Currency</label><select id="currency" name="currency">'+['NZD','USD','AUD','GBP','EUR'].map(c=>`<option ${p.currency===c?'selected':''}>${c}</option>`).join('')+'</select>'+field('tax','Tax wording');break}
open(title,html,data=>{const next={...p};for(const[k,v]of data)next[k]=['rate','days','costs','fee','deposit','reviews','conceptDays','animationDays','reviewDays','finishDays'].includes(k)?Number(v):v.trim();if(!next.title||!next.client||!validate(next)){toast('Please check your project details.');return}Object.assign(p,next);save();dialog.close();toast('Project updated')});if(kind==='pricing'){const update=()=>$('#estimate').textContent=money(Number($('#rate').value)*Number($('#days').value)+Number($('#costs').value));['rate','days','costs'].forEach(k=>$('#'+k).addEventListener('input',update));update()}}
function download(name,data){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type:'application/json'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function share(){const url=location.origin+location.pathname+'#project='+encode(p);open('One page. One link.','<p class="hint">Anyone with this link can view this version without a login. It includes the client-facing scope, dates, price and terms. Your working rates and costs are left out.</p><label for="share-link">Client link</label><textarea id="share-link" readonly></textarea><p class="hint">This is a fixed snapshot. If you change the project, send a new link. Links cannot be revoked. Agreement and payment happen directly with you.</p>',async()=>{try{await navigator.clipboard.writeText(url);toast('Client link copied');dialog.close()}catch{$('#share-link').select();toast('Select and copy the link above.')}},'Copy client link ↗');$('#share-link').value=url}
function projectList(){open('Your project notes',`<div class="project-list">${projects.map((v,i)=>`<button type="button" data-project="${i}">${esc(v.title)}<small>${esc(v.client)}</small></button>`).join('')}</div><div style="display:flex;gap:8px;margin-top:20px"><button type="button" data-action="new">+ New project</button><button type="button" data-action="export">Export backup ↓</button><button type="button" data-action="import">Import backup ↑</button></div><p class="hint">Drafts stay in this browser. Export a backup to move them to another device.</p>`,null)}
document.addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;if(button.dataset.stage!==undefined){const s=stages(p)[Number(button.dataset.stage)];open(s.name,`<span class="stage-owner">${esc(s.owner)}</span><p class="hint">${date(s.start)}${s.start!==s.end?' — '+date(s.end):''}</p><div class="stage-detail" style="white-space:pre-line">${esc(s.body)}</div>`,null);return}if(button.dataset.project!==undefined&&!readonly){p=projects[Number(button.dataset.project)];dialog.close();render();return}const a=button.dataset.action;if(a==='agreement'){showAgreement();return}if(a==='back-project'){closeAgreement();return}if(a==='download-agreement'){downloadAgreement();return}if(readonly)return;if(a==='preview'){preview=!preview;render()}else if(a==='share')share();else if(a==='projects')projectList();else if(a==='new'){p=example();p.title='Untitled project';p.client='Client name';projects.unshift(p);save();dialog.close();edit('project')}else if(a==='export')download('seabird-projects-backup.json',JSON.stringify(projects,null,2));else if(a==='import'){const input=document.createElement('input');input.type='file';input.accept='.json';input.onchange=async()=>{try{const file=input.files[0];if(file.size>2000000)throw Error();const items=JSON.parse(await file.text());if(!Array.isArray(items)||!items.length||items.length>100||!items.every(validate))throw Error();for(const item of items){projects.push({...item,id:crypto.randomUUID(),rate:Number(item.rate)||0,days:Number(item.days)||1,costs:Number(item.costs)||0})}save();dialog.close();toast('Backup imported')}catch{toast('This file is not a valid Seabird project backup.')}};input.click()}else if(a)edit(a)});
$('#close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});window.addEventListener('hashchange',()=>location.reload());render();if(!readonly)save();

function editDeliverables(){
  const itemFields=(v)=>'<div class="deliverable-editor"><label>Item name<input class="item-name" maxlength="200" required value="'+esc(v.name)+'" placeholder="Opening title sequence — 4K master"></label><label>Technical specifications<textarea class="item-specs" maxlength="2000" placeholder="Resolution, frame rate, pixel aspect, codec / compression, colour space…">'+esc(v.specs)+'</textarea></label><button type="button" class="remove-deliverable">Remove item</button></div>';
  open('The deliverables','<p class="hint">Name each item, then add its delivery specifications. For video: square pixels, 4:2:2, Rec.709, plus resolution, frame rate and codec as needed.</p><div id="deliverable-editors">'+deliverableItems(p).map(itemFields).join('')+'</div><button type="button" id="add-deliverable">+ Add item</button>',()=>{
    const items=Array.from(document.querySelectorAll('.deliverable-editor'),el=>({name:el.querySelector('.item-name').value.trim(),specs:el.querySelector('.item-specs').value.trim()}));
    const next={...p,deliverableItems:items,deliverables:items.map(v=>v.name).join('\n')};
    if(!validate(next)){toast('Add at least one named deliverable, up to 30 items.');return}
    Object.assign(p,next);save();dialog.close();toast('Deliverables updated');
  });
  $('#add-deliverable').onclick=()=>{if(document.querySelectorAll('.deliverable-editor').length>=30){toast('You can add up to 30 items.');return}$('#deliverable-editors').insertAdjacentHTML('beforeend',itemFields({name:'',specs:''}));$('#deliverable-editors').lastElementChild.querySelector('input').focus()};
  $('#deliverable-editors').onclick=e=>{if(e.target.closest('.remove-deliverable'))e.target.closest('.deliverable-editor').remove()};
}

let agreementUrl=null,agreementFilename='',agreementRequest=0;
async function showAgreement(){
 const request=++agreementRequest;
 $('#actions').innerHTML='<button data-action="back-project">← Back to project</button><button class="primary" data-action="download-agreement" disabled>Download PDF ↓</button>';
 $('#app').innerHTML='<section class="agreement-view"><div class="agreement-intro"><span class="section-label">THE COMPLETE PICTURE</span><h1>Your project, on paper.</h1><p>All five sections, the full timeline, and signature spaces for Roll and '+esc(p.client)+'. Ready to download, email and sign.</p></div><p id="pdf-status" role="status">Preparing your agreement…</p><iframe id="agreement-preview" title="Project agreement PDF preview" hidden></iframe></section>';
 try{const blob=await agreementBlob(p);if(request!==agreementRequest)return;if(agreementUrl)URL.revokeObjectURL(agreementUrl);agreementUrl=URL.createObjectURL(blob);agreementFilename=(p.title.replace(/[^a-z0-9]+/gi,'-').replace(/^-|-$/g,'')||'project')+'-agreement.pdf';$('#agreement-preview').src=agreementUrl;$('#agreement-preview').hidden=false;$('#pdf-status').textContent='Preview the exact PDF below. If your browser cannot display it, use Download PDF.';$('[data-action="download-agreement"]').disabled=false}
 catch(err){if(request!==agreementRequest)return;$('#pdf-status').textContent='The PDF could not be generated. Go back to the project and try again.';toast('Could not generate agreement. Please try again.')}
}
function closeAgreement(){agreementRequest++;if(agreementUrl){URL.revokeObjectURL(agreementUrl);agreementUrl=null}render()}
function downloadAgreement(){if(!agreementUrl)return;const a=document.createElement('a');a.href=agreementUrl;a.download=agreementFilename;document.body.append(a);a.click();a.remove()}
document.addEventListener('toggle',e=>{if(e.target.matches('.project-card')&&e.target.open)document.querySelectorAll('.project-card').forEach(card=>{if(card!==e.target)card.open=false})},true);
